#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "doitgen.h"


/* Array initialization. */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++)
	A[i][j][k] = (DATA_TYPE) ((i*j + k)%np) / np;
  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++)
      C4[i][j] = (DATA_TYPE) (i*j % np) / np;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* nr, nq, np are carried through the interface for consistency with
   * the PolyBench harness; the actual loop bounds are the polybench-
   * specific _PB_* macros, as in the original code. */
  (void)nr;
  (void)nq;
  (void)np;

#pragma scop
  /* Optimized kernel:
   *
   * Original structure (for each fixed (r, q)):
   *
   *   for (p)
   *     sum[p] = 0;
   *     for (s)
   *       sum[p] += A[r][q][s] * C4[s][p];
   *   for (p)
   *     A[r][q][p] = sum[p];
   *
   * This reads A[r][q][s] NP times (once for every p), and accesses
   * C4[s][p] with s varying fastest, which is a stride-NP access.
   *
   * New structure (for each fixed (r, q)):
   *
   *   1) Initialize sum[p] once.
   *   2) Loop over s outside, and for each s:
   *        - load A[r][q][s] once,
   *        - update all sum[p] over contiguous p using C4[s][p].
   *   3) Copy sum[p] back to A[r][q][p].
   *
   * This:
   *   - keeps the per-(r,q,p) accumulation order over s identical to
   *     the original code (s goes 0..NP-1 in both versions),
   *   - loads each A[r][q][s] only once per (r,q),
   *   - accesses both C4[s][p] and sum[p] contiguously in p, which
   *     is cache- and SIMD-friendly.
   */

  for (r = 0; r < _PB_NR; r++)
    for (q = 0; q < _PB_NQ; q++) {
      /* 1. Initialize the temporary accumulation vector for this (r, q). */
      for (p = 0; p < _PB_NP; p++)
        sum[p] = SCALAR_VAL(0.0);

      /* 2. Matrix-vector style accumulation: s outer, p inner.
       *    For each s, we:
       *      - load A[r][q][s] once into a scalar,
       *      - walk C4[s][p] and sum[p] contiguously in p.
       */
      for (s = 0; s < _PB_NP; s++) {
        DATA_TYPE a_rqs = A[r][q][s];     /* reused across all p for this s */
        DATA_TYPE *c4_row = C4[s];        /* pointer to row s of C4 */

        /* Inner loop has no loop-carried dependencies over p and
         * touches contiguous elements of both c4_row and sum, making
         * it a good target for auto-vectorization by the compiler. */
        for (p = 0; p < _PB_NP; p++) {
          sum[p] += a_rqs * c4_row[p];
        }
      }

      /* 3. Write back the transformed row from sum[] into A. */
      for (p = 0; p < _PB_NP; p++)
        A[r][q][p] = sum[p];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int nr = NR;
  int nq = NQ;
  int np = NP;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A,DATA_TYPE,NR,NQ,NP,nr,nq,np);
  POLYBENCH_1D_ARRAY_DECL(sum,DATA_TYPE,NP,np);
  POLYBENCH_2D_ARRAY_DECL(C4,DATA_TYPE,NP,NP,np,np);

  /* Initialize array(s). */
  init_array (nr, nq, np,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(C4));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_doitgen (nr, nq, np,
		  POLYBENCH_ARRAY(A),
		  POLYBENCH_ARRAY(C4),
		  POLYBENCH_ARRAY(sum));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(nr, nq, np,  POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(sum);
  POLYBENCH_FREE_ARRAY(C4);

  return 0;
}
