		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Create local restrict-qualified aliases to help the compiler
     with alias analysis and vectorization.  The PolyBench macros
     expand to VLA parameters; we capture them in pointers that
     carry the 'restrict' qualifier. */
  DATA_TYPE (*restrict A_)[nq][np] = A;
  DATA_TYPE (*restrict C4_)[np]    = C4;
  DATA_TYPE *restrict sum_         = sum;

#pragma scop
  /* For each (r, q), treat A_[r][q][*] as a length-NP row vector and
     apply the common NP×NP transform matrix C4_ on the right:

         A_new[r, q, p] = sum_{s=0..NP-1} A_old[r, q, s] * C4[s, p]

     Compared to the original implementation, we restructure the
     inner loops as:

       for p: sum[p] = 0;
       for s:
         a = A[r, q, s];
         for p: sum[p] += a * C4[s, p];
       for p: A[r, q, p] = sum[p];

     This:
       - keeps accesses to C4 and sum contiguous in 'p',
       - loads each A[r, q, s] once and reuses it across all p,
       - is algebraically equivalent to the original, differing only
         in the order of floating-point additions. */
  for (r = 0; r < _PB_NR; r++)
  {
    for (q = 0; q < _PB_NQ; q++)
    {
      DATA_TYPE *restrict sum_local = sum_;
      DATA_TYPE *restrict A_rq      = &A_[r][q][0];

      /* 1. Initialize the accumulation buffer for this (r, q). */
      for (p = 0; p < _PB_NP; p++)
        sum_local[p] = SCALAR_VAL(0.0);

      /* 2. Reduction over s with p as the innermost loop.
             - A_rq[s]  is contiguous in s (last dimension of A).
             - C4_[s][p] and sum_local[p] are contiguous in p.
         This loop structure is cache-friendly and amenable to SIMD. */
      for (s = 0; s < _PB_NP; s++)
      {
        const DATA_TYPE a_val = A_rq[s];
        const DATA_TYPE *restrict C4_row = C4_[s];

        /* No loop-carried dependencies across p: each iteration touches
           a distinct sum_local[p].  Hint the compiler to vectorize and
           unroll this loop aggressively. */
#pragma GCC ivdep
#pragma GCC unroll 8
        for (p = 0; p < _PB_NP; p++)
        {
          sum_local[p] += a_val * C4_row[p];
        }
      }

      /* 3. Write the transformed vector back to A.
         All reads of A_rq[*] are complete, so overwriting in-place
         is safe and preserves the intended semantics. */
#pragma GCC ivdep
#pragma GCC unroll 8
      for (p = 0; p < _PB_NP; p++)
      {
        A_rq[p] = sum_local[p];
      }
    }
  }
#pragma endscop

}


