/* Array initialization. */
static
void init_array(int nr, int nq, int np,
		DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np))
{
  int i, j, k;

  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++)
	A[i][j][k] = (DATA_TYPE) ((i*j + k)%np) / np;
  for (i = 0; i < np; i++)
    for (j = 0; j < np; j++)
      C4[i][j] = (DATA_TYPE) (i*j % np) / np;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int nr, int nq, int np,
		 DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np))
{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < nr; i++)
    for (j = 0; j < nq; j++)
      for (k = 0; k < np; k++) {
	if ((i*nq*np+j*np+k) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
void kernel_doitgen[[gnu::flatten, gnu::noinline]](int nr, int nq, int np,
		    DATA_TYPE POLYBENCH_3D(A,NR,NQ,NP,nr,nq,np),
		    const DATA_TYPE POLYBENCH_2D(C4,NP,NP,np,np),
		    DATA_TYPE POLYBENCH_1D(sum,NP,np))
{
  int r, q, p, s;

  /* Create local restrict-qualified views of the arrays to help the
     compiler with alias analysis and vectorization. We know from the
     benchmark that A, C4 and sum are distinct allocations. */
  DATA_TYPE (* restrict A_)[nq][np] =
      (DATA_TYPE (* restrict)[nq][np]) A;
  const DATA_TYPE (* restrict C4_)[np] =
      (const DATA_TYPE (* restrict)[np]) C4;
  DATA_TYPE * restrict sum_ =
      (DATA_TYPE * restrict) sum;

#pragma scop
  /* Optimized loop structure:
     For each (r, q), we conceptually compute:
       A[r,q,p] = sum_s A[r,q,s] * C4[s,p]

     Original code (inefficient for locality):
       for p:
         sum[p] = 0;
         for s:
           sum[p] += A[r][q][s] * C4[s][p];
       for p:
         A[r][q][p] = sum[p];

     Optimized code:
       1. Initialize all sum[p] once.
       2. For each s, load A[r,q,s] once and reuse it across all p:
            a_val = A[r,q,s];
            for p:
              sum[p] += a_val * C4[s][p];
          This makes p the innermost loop, so both C4[s][p] and sum[p]
          are accessed contiguously in memory and are easy to vectorize.
       3. Write back sum[p] to A[r,q,p].

     For each fixed (r,q,p), the sequence of additions over s still
     occurs in ascending s order, so the floating-point reduction order
     matches the original implementation. */
  for (r = 0; r < _PB_NR; r++) {
    for (q = 0; q < _PB_NQ; q++) {
      DATA_TYPE * restrict A_rq = &A_[r][q][0];

      /* Step 1: initialize accumulation buffer. */
      for (p = 0; p < _PB_NP; p++) {
        sum_[p] = SCALAR_VAL(0.0);
      }

      /* Step 2: perform the NP×NP transform for this (r, q) slice.
         s is the reduction dimension, p is innermost for contiguous
         accesses and good SIMD opportunities. */
      for (s = 0; s < _PB_NP; s++) {
        const DATA_TYPE a_val = A_rq[s];
        const DATA_TYPE * restrict C4_row = &C4_[s][0];

        for (p = 0; p < _PB_NP; p++) {
          sum_[p] += a_val * C4_row[p];
        }
      }

      /* Step 3: write back the result to A. */
      for (p = 0; p < _PB_NP; p++) {
        A_rq[p] = sum_[p];
      }
    }
  }
#pragma endscop

}


